// Telegram send confirmation for Claude Code.
//
// A `tg-session send ... --confirm` call is held, and the user is asked in
// Claude's own question dialog: who it goes to and what it says. "Отправить"
// writes a one-time approval (account, target, text, media) that the sending
// tool checks and deletes; anything else refuses the call.
//
// The host reads `on(...)` and `$.noun.method(...)` from source, so they are
// spelled literally, and helpers that take `$` are top-level functions.

// Nothing but this mod may touch the approval file.
const APPROVAL_FILE = ".tg-claude-approval";
const APPROVAL_SCRIPT = `umask 077; printf %s "$1" > "$HOME/.claude/${APPROVAL_FILE}"`;

// One question at a time: a second send waits for the first answer.
let queue = Promise.resolve();

export function register(on) {
  on("tool.call", async ($, e, next) => {
    if (JSON.stringify(e).includes(APPROVAL_FILE)) {
      return { deny: "Файл подтверждения Telegram записывается только ответом пользователя. Не трогай его." };
    }
    return next(e);
  });

  on("tool.call", { tool: "Bash" }, async ($, e, next) => {
    const send = parseSend(String(e.command ?? ""));
    if (send === null) {
      return next(e);
    }
    const turn = queue.then(() => ask($, send));
    queue = turn.catch(() => {});
    let answer = null;
    try {
      answer = await turn;
    } catch {
      // dismissed, or nobody to ask
    }
    if (answer !== "Отправить") {
      return { deny: "Пользователь не подтвердил отправку в Telegram, ничего не отправлено. Не повторяй без его просьбы." };
    }
    const approved = JSON.stringify({ account: send.account, target: send.target, text: send.text ?? null, media: send.media ?? null });
    const run = await $.process.run(["bash", "-c", APPROVAL_SCRIPT, "tg-confirm", approved], { timeoutMs: 5000 });
    if (run.exitCode !== 0) {
      return { deny: "Не удалось записать подтверждение, ничего не отправлено." };
    }
    return next(e);
  });
}

async function ask($, send) {
  if (send.text === undefined && send.file !== undefined) {
    const run = await $.process.run(["cat", "--", send.file], { cwd: await $.session.cwd(), timeoutMs: 5000 });
    send.text = run.exitCode === 0 ? run.stdout : undefined;
  }
  const parts = [
    "Отправить сообщение в Telegram?",
    `Кому: ${send.target === "me" ? "Избранное" : send.target}\nС аккаунта: ${send.account}`,
    send.text ?? (send.media ? null : "(не удалось прочитать текст)"),
    send.media ? `Вложение: ${send.media}` : null,
  ];
  return $.ui.ask(parts.filter(Boolean).join("\n\n"), { header: "Telegram", options: ["Отмена", "Отправить"] });
}

/** `tg-session send ... --confirm`, or null. Read from the whole line so quoted text with ; or newlines stays intact. */
function parseSend(command) {
  if (!/tg-session|tg_user_session/.test(command) || !/--confirm\b/.test(command)) {
    return null;
  }
  const words = tokenize(command);
  const at = words.findIndex((w) => /(^|\/)tg-session$/.test(w) || w === "tg_user_session.cli");
  if (at < 0 || words[at + 1] !== "send" || !words.includes("--confirm")) {
    return null;
  }
  const args = words.slice(at + 2);
  const opt = (name) => {
    const i = args.indexOf(name);
    if (i >= 0) return args[i + 1];
    return args.find((a) => a.startsWith(`${name}=`))?.slice(name.length + 1);
  };
  const positional = [];
  for (let i = 0; i < args.length; i += 1) {
    if (args[i].startsWith("--")) {
      if (!args[i].includes("=") && !["--confirm", "--yes", "--json"].includes(args[i])) i += 1;
    } else if (positional.length < 2) {
      positional.push(args[i]);
    }
  }
  return { account: positional[0] ?? "?", target: positional[1] ?? "?", text: opt("--text"), file: opt("--file"), media: opt("--media") };
}

/** Splits a command into words, honouring quotes. */
function tokenize(text) {
  const words = [];
  const re = /"((?:[^"\\]|\\.)*)"|'([^']*)'|(\S+)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    words.push(m[1] !== undefined ? m[1].replace(/\\(.)/g, "$1") : (m[2] ?? m[3]));
  }
  return words;
}

